import{_ as e,o as a,c as s,ai as i}from"./chunks/framework.BxxKhjs3.js";const t="/pub-blog/assets/shouyewenda.DySRz5Br.gif",o="/pub-blog/assets/image-20250624114248485.WdLD1nbY.png",r="/pub-blog/assets/image-20250624114343186.CkkYuXpT.png",g="/pub-blog/assets/image-20250624114430891.CGi0Tnb5.png",p="/pub-blog/assets/image-20250624114515701.BWMl9W3B.png",m="/pub-blog/assets/image-20250624114715890.pnPC1FIn.png",l="/pub-blog/assets/image-20250624115130952.BL1aNKqK.png",c="/pub-blog/assets/image-20250624115203420.Cz7x3mF3.png",d="/pub-blog/assets/image-20250624115402283.CIAaTuaz.png",_="/pub-blog/assets/image-20250624115510171.DsIz1hrZ.png",h="/pub-blog/assets/image-20250624120328745.Cnba7Gxx.png",u="/pub-blog/assets/image-20250624120502467.Cwii6Zqh.png",b="/pub-blog/assets/image-20250624120625448.DDdS1uAI.png",A="/pub-blog/assets/image-20250624120837857.js4GgLKX.png",f="/pub-blog/assets/image-20250624120922812.BqZRercU.png",I="/pub-blog/assets/image-20250624121058761.BibBn5ag.png",C="/pub-blog/assets/image-20250624121113276.BaDfCmmH.png",q="/pub-blog/assets/image-20250624121126453.DwQfXZje.png",k="/pub-blog/assets/image-20250624121429824.DVHTYCcL.png",G="/pub-blog/assets/image-20250622200325374.BLr7GNE1.png",B=JSON.parse('{"title":"重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程/重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程.md","filePath":"鸿蒙开发技巧/重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程/重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程.md","lastUpdated":1750738675000,"__rawMarkdown":"# 重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程\\n\\n## AI 辅助编程（CodeGenie）\\n\\nDevEco AI辅助编程工具（CodeGenie）基于BitFun Platform AI能力平台，为开发者提供高效的应用与服务AI编程支持，支持智能知识问答，同时支持ArkTS代码生成和万能卡片生成能力，帮助开发者提高编码效率\\n\\n![img](assets/shouyewenda.gif)\\n\\n## 核心功能\\n\\n目前 CodeGenie 提供了 几大核心功能\\n\\n- **智能问答**\\n- **代码生成**\\n- **页面生成**\\n- **应用UI生成**\\n- **万能卡片生成**\\n- 单元测试用例生成\\n- **代码智能解读**\\n- **编译报错智能调优**\\n- 智慧调优\\n\\n可以看到，这些AI功能都是程序员开发必备的香饽饽。\\n\\n![image-20250624114248485](assets/image-20250624114248485.png)\\n\\n\\n\\n\\n\\n## 下载安装\\n\\n通过[下载中心](https://developer.huawei.com/consumer/cn/download/deveco-codegenie)下载，然后通过**dev eco** 离线安装\\n\\n![image-20250624114343186](assets/image-20250624114343186.png)\\n\\n得到压缩包\\n\\n![image-20250624114430891](assets/image-20250624114430891.png)\\n\\n然后进行离线安装\\n\\n![image-20250624114515701](assets/image-20250624114515701.png)\\n\\n最后记得重启`DevEco Studio`一下\\n\\n\\n\\n## 登录\\n\\n> 智能辅助鸿蒙应用开发\\n>\\n> DeepSeek+盘古 双擎驱动\\n>\\n> ---\\n>\\n> 上面听着就牛逼😄\\n\\n![image-20250624114715890](assets/image-20250624114715890.png)\\n\\n\\n\\n## 智能问答\\n\\n**问：现在鸿蒙开发推荐使用什么样的路由解决方案**\\n\\n**答：**\\n\\n![image-20250624115130952](assets/image-20250624115130952.png)\\n\\n\\n\\n\\n\\n可以看到效果还很不错了，其中还能找到我的[技术文章](https://developer.huawei.com/consumer/cn/forum/topic/0202184521504306179) 哈哈\\n\\n![image-20250624115203420](assets/image-20250624115203420.png)\\n\\n\\n\\n\\n\\n## 内联对话\\n\\n编写代码边问答，感受一下\\n\\n![image-20250624115402283](assets/image-20250624115402283.png)\\n\\n![image-20250624115510171](assets/image-20250624115510171.png)\\n\\n\\n\\n\\n\\n## 问题修复\\n\\n当我们程序构建错误时，可以利用问题修复功能协助排查\\n\\n![image-20250624120328745](assets/image-20250624120328745.png)\\n\\n---\\n\\n提示需要开启授权\\n\\n![image-20250624120502467](assets/image-20250624120502467.png)\\n\\n---\\n\\n这个时候帮我们提示修复了\\n\\n![image-20250624120625448](assets/image-20250624120625448.png)\\n\\n\\n\\n\\n\\n## 页面生成\\n\\n这个是我比较关心的重磅功能！\\n\\n对于开发鸿蒙页面来讲，如果有AI的直接支持，可以大大提高我们的开发效率，之前其他的ai工具、cursor、trae也好，都没有办法很好的支持鸿蒙应用的开发，现在我们感受下 **CodeGenie**的能力。\\n\\n![image-20250624120837857](assets/image-20250624120837857.png)\\n\\n---\\n\\n然后根据需求进行操作\\n\\n![image-20250624120922812](assets/image-20250624120922812.png)\\n\\n---\\n\\n得到内容\\n\\n![image-20250624121058761](assets/image-20250624121058761.png)\\n\\n---\\n\\n保存到工程\\n\\n![image-20250624121113276](assets/image-20250624121113276.png)\\n\\n---\\n\\n![image-20250624121126453](assets/image-20250624121126453.png)\\n\\n---\\n\\n修改启动页面，然后运行起来\\n\\n![image-20250624121429824](assets/image-20250624121429824.png)\\n\\n\\n\\n\\n\\n## 关于我们\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250622200325374](assets/image-20250622200325374.png)"}'),S={name:"鸿蒙开发技巧/重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程/重磅推出🔥 HarmonyOS AI助手  CodeGenie V6的使用教程.md"};function w(P,n,v,x,y,D){return a(),s("div",null,[...n[0]||(n[0]=[i("",61)])])}const H=e(S,[["render",w]]);export{B as __pageData,H as default};
